import {studioOpening} from './studio-opening.js?v=20260921-personas2';
import {people} from './data.js?v=20260921-streamlined2';

const themes=['First-day readiness','Franchisee onboarding','Identity continuity','Shared-device access','Franchise device standard','Access governance','Remote contractor','Offboarding evidence'];
const tones=['#20f593','#f0c994','#c398ff','#b9b1ff','#83c5ff','#f0c994','#83c5ff','#ff9a9a'];
const externalLensPeople=new Set(['elena','samfed','sam','tom']);

function externalJourneys(){return `<section class="external-journey-section" aria-labelledby="external-journeys-title"><div class="identity-model-label"><span>EXTERNAL ID</span><strong>External tenant</strong><small>Customer and business-customer applications</small></div><div class="external-journey-heading"><div><span class="eyebrow">MICROSOFT ENTRA EXTERNAL ID</span><h2 id="external-journeys-title">Three partner journeys. Three business boundaries.</h2></div><p>Use these journeys to teach partner sign-up, business verification, application authorization, machine credentials and evidence. The people are the same identities you sign in with on the live portals.</p></div><div class="external-journey-grid"><article class="vendor-feature partner-feature primary-external-journey"><div class="external-card-person"><img src="./assets/personas/evan-torres.webp" alt="Evan Torres"><div><div class="eyebrow">PARTNER DEVELOPER ACCESS</div><span class="primary-journey-badge">PRIMARY LIVE PROOF · 60 MIN</span><h3>Evan Torres · register the integration, protect the API</h3><p>Run the complete External ID sequence: branded sign-up, trusted partner verification, an allowed sandbox request, a denied production action and correlated evidence.</p><div class="journey-proof-row"><span>Sign up</span><span>Allow</span><span>Deny</span><span>Evidence</span></div><span class="journey-demo-status connected">Live Integration Exchange + API</span></div></div><a class="outline" href="#evan/experience">Start primary journey →</a></article><article class="vendor-feature"><div class="external-card-person"><img src="./assets/personas/tom-reilly.webp" alt="Tom Reilly"><div><div class="eyebrow">VENDOR COORDINATION</div><h3>Tom Reilly · ClimateWorks on the Supplier Desk</h3><p>Branded onboarding, vendor verification, property assignments, recovery and work-order authorization.</p><div class="journey-proof-row"><span>User flow</span><span>Business context</span><span>API boundary</span></div><span class="journey-demo-status connected">Live External ID app + API</span></div></div><a class="outline" href="#tom-vendor/experience">Explore vendor journey →</a></article><article class="vendor-feature franchise-feature"><div class="external-card-person"><img src="./assets/personas/elena-petrova.webp" alt="Elena Petrova"><div><div class="eyebrow">FRANCHISE OPERATIONS · 45 MIN</div><h3>Elena Petrova · Bayside Hotels in the Franchise Hub</h3><p>Business verification, location-scoped authority, step-up, delegation, transfer and audit evidence.</p><div class="journey-proof-row"><span>External tenant</span><span>Location scope</span><span>Allow + deny</span></div><span class="journey-demo-status connected">Live Franchise Hub + API</span></div></div><a class="outline" href="#elena-franchise/experience">Explore franchise journey →</a></article></div></section>`;}
function workforceJourneys(){return `<section class="workforce-journey-section" aria-labelledby="workforce-journeys-title"><div class="identity-model-label workforce"><span>WORKFORCE ID</span><strong>Workforce tenant</strong><small>Employees, guests and organizational resources</small></div><div class="home-section-heading"><h2 id="workforce-journeys-title">Eight stories, seven people, in order of arrival.</h2><span>Story → Live demo → How AI helps</span></div><div class="workforce-context"><p>Each use case is a moment in a working shift rather than a blade in a portal. The order matches the client deck.</p><span>Stories 2 and 5 cross into External ID and federation; the rest stay in the workforce tenant.</span></div><section class="home-personas" aria-label="Choose a workforce persona">${people.map((p,i)=>`<article class="home-persona" style="--persona-tone:${tones[i]}"><div class="home-card-top"><span class="home-avatar"><img src="${p.portrait}" alt="${p.name}"></span><span class="home-topic">${themes[i]}</span><span class="home-card-arrow" aria-hidden="true">↗</span></div><h3>${p.name}</h3><div class="home-job">${p.job}</div><h4>${p.role}</h4><p>${p.intro}</p><div class="home-card-foot"><span>${p.moments.length} story moments</span>${externalLensPeople.has(p.id)?'<span class="external-lens-badge">External ID lens</span>':''}</div><div class="home-card-actions"><button class="primary" data-action="person" data-value="${i}">Explore story →</button><button class="outline" data-action="person-ai" data-value="${i}">✦ How AI helps</button></div></article>`).join('')}</section></section>`;}

export function homePage(){return `<div class="home-shell"><header class="home-header"><a href="#home" aria-label="MajorKey workshop home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="180" height="32"></a><span>IDENTITY EXPERIENCE STUDIO</span><button class="quiet studio-prep" data-action="ready">Presenter preparation</button><button class="quiet" data-action="agenda">Workshop agenda ↗</button></header><main class="home-main">${studioOpening}${externalJourneys()}${workforceJourneys()}<footer class="home-footer"><span>MajorKey · Harborline reference lab · Azure edition</span><div><button class="quiet" data-action="catalog">Browse 34 use cases</button><button class="quiet" data-action="ready">Presenter preparation</button></div></footer></main></div><dialog id="modal" aria-labelledby="modal-title"></dialog>`;}
